// Production client-page integration example.
// Uses only the public Supabase URL + anon key.
// For a PRIVATE storage bucket, download links should be generated by a protected Edge Function.
// This example shows the metadata query only.
const { data, error } = await supabaseClient
  .from("bot_releases")
  .select("version,release_date,release_notes,file_path,original_filename")
  .eq("published", true)
  .order("created_at", { ascending:false })
  .limit(1)
  .maybeSingle();
